(() => {
 'use strict';const R=window.NastranRelations,$=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current='101',lastWidth=0;
 function draw(){const width=Math.max(280,Math.floor($('relation-view').clientWidth));lastWidth=width;$('relation-view').innerHTML=R.render(current,width);}
 function route(){const match=/^#sol-(101|103|111|112)$/.exec(location.hash);current=match?match[1]:'101';const map=R.maps[current];document.querySelectorAll('.rel-tabs a').forEach(a=>{if(a.hash==='#sol-'+current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('relation-title').textContent='SOL '+current+' · '+map.title;$('relation-subtitle').textContent=map.subtitle;$('relation-input').href=map.input;$('relation-notes').innerHTML=map.notes.map(s=>'<li>'+esc(s)+'</li>').join('');$('relation-settings').innerHTML=map.settings.map(s=>'<li>'+esc(s)+'</li>').join('');draw();}
 function openNode(element){const [i,key]=element.dataset.relNode.split(':'),p=R.maps[current].panels[Number(i)],n=p.nodes.find(n=>n.key===key);if(!n)return;const map=R.maps[current];$('relation-dialog-title').textContent=n.title;$('relation-dialog-kind').textContent={case:'Case Control · 条件を選ぶ',bulk:'Bulk Data · 条件の中身',param:'Bulk Data · PARAM設定',ground:'模型の固定側'}[n.kind];$('relation-dialog-ids').textContent=n.ids.length?n.ids.join('\n'):n.role;$('relation-dialog-help').textContent=n.help;
  const names=new Map(p.nodes.map(n=>[n.key,n]));let links='';for(const [title,edges,property]of [['このカードから見る先',p.edges.filter(e=>e.from===key),'to'],['このカードを使う元',p.edges.filter(e=>e.to===key),'from']]){if(edges.length)links+='<h3>'+title+'</h3><ul>'+edges.map(e=>'<li>'+esc(names.get(e[property]).title)+'：'+esc(e.label)+(e.dashed?'（設定の作用）':'（番号の参照）')+'</li>').join('')+'</ul>';}$('relation-dialog-links').innerHTML=links;
  $('relation-card-link').hidden=!n.card;$('relation-card-link').href=current==='101'?'bulk.html#'+n.card:'dynamics.html#card-'+n.card;$('relation-deck-link').href=map.input;$('relation-dialog').showModal();
 }
 $('relation-view').addEventListener('click',e=>{const target=e.target.closest('[data-rel-node]');if(target)openNode(target);});$('relation-view').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const target=e.target.closest('[data-rel-node]');if(target){e.preventDefault();openNode(target);}}});$('relation-close').addEventListener('click',()=>$('relation-dialog').close());$('relation-dialog').addEventListener('click',e=>{if(e.target===$('relation-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
 window.addEventListener('hashchange',route);let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(Math.floor($('relation-view').clientWidth)!==lastWidth)draw();},120);});route();
})();
